/* Host-app bridge: when this page runs inside the app's iframe, the back chevron
   hands navigation back to the parent instead of doing nothing. */
(function(){
  if(window.parent === window) return;   // standalone (artifact/dev server): no-op
  var back=document.getElementById('backBtn');
  if(back) back.addEventListener('click', function(){ window.parent.postMessage({type:'eco-tree-nav', to:'tree-overview'}, '*'); });
})();
